#include <limits>
#include <iostream>

struct CustomType {};

int main() {
    // Standard type is specialized
    if (std::numeric_limits<int>::is_specialized) {
        std::cout << "int is specialized.\n";
    }

    // User-defined type (typically not specialized)
    if (!std::numeric_limits<CustomType>::is_specialized) {
        std::cout << "CustomType is NOT specialized.\n";
    }

    // Accessing a property (e.g., digits)
    const int int_digits = std::numeric_limits<int>::digits;
    // const int custom_digits = std::numeric_limits<CustomType>::digits; // Likely 0
}
